<template>
  <main class="page"><section class="wrap">
    <header class="hero"><div><span>DELIVERY PROFILE</span><h1>My addresses</h1><p>Save your delivery destinations so Stokvel purchases can be sent directly to your share.</p></div><RouterLink class="back" to="/profile">← Profile</RouterLink></header>
    <div v-if="error" class="message">{{ error }}</div><div v-if="success" class="success">{{ success }}</div>
    <section class="layout">
      <article class="panel"><div class="panel-head"><div><span class="label">ADDRESS BOOK</span><h2>Your delivery destinations</h2></div><span class="count">{{ addresses.length }}</span></div>
        <div v-if="loading" class="empty">Loading addresses…</div>
        <div v-else-if="!addresses.length" class="empty">You do not have a saved address yet. Add one so you can receive individual Stokvel allocations.</div>
        <div v-else class="addresses"><article v-for="address in addresses" :key="address.address_id" class="address-card"><div class="address-top"><div><span class="tag">{{ address.label }}</span><strong>{{ address.recipient_name }}</strong></div><span v-if="address.is_default" class="default">DEFAULT</span></div><p>{{ address.address_line_1 }}<template v-if="address.address_line_2">, {{ address.address_line_2 }}</template><br>{{ address.city }}, {{ address.province }} {{ address.postal_code }}</p><small v-if="address.phone_number">{{ address.phone_number }}</small><div class="address-actions"><button v-if="!address.is_default" type="button" @click="makeDefault(address.address_id)">Make default</button><button type="button" @click="edit(address)">Edit</button><button class="danger" type="button" @click="remove(address.address_id)">Delete</button></div></article></div>
      </article>
      <form class="panel form" @submit.prevent="save"><div><span class="label">{{ editingId ? 'EDIT ADDRESS' : 'NEW ADDRESS' }}</span><h2>{{ editingId ? 'Update your address' : 'Add an address' }}</h2></div>
        <div class="grid"><label>Label<input v-model="form.label" placeholder="Home" required></label><label>Recipient name<input v-model="form.recipient_name" placeholder="Full name" required></label><label>Phone number<input v-model="form.phone_number" placeholder="082 123 4567"></label><label>Postal code<input v-model="form.postal_code" placeholder="7784" required></label><label class="wide">Address line 1<input v-model="form.address_line_1" placeholder="Street and number" required></label><label class="wide">Address line 2<input v-model="form.address_line_2" placeholder="Unit, suburb or complex (optional)"></label><label>City<input v-model="form.city" placeholder="Cape Town" required></label><label>Province<input v-model="form.province" placeholder="Western Cape" required></label></div>
        <label class="check"><input v-model="form.is_default" type="checkbox"> Use this as my default delivery address</label>
        <div class="form-actions"><button v-if="editingId" type="button" class="secondary" @click="reset">Cancel</button><button class="primary" type="submit" :disabled="saving">{{ saving ? 'Saving…' : editingId ? 'Save changes' : 'Add address' }}</button></div>
      </form>
    </section>
  </section></main>
</template>
<script setup>
import { onMounted, reactive, ref } from 'vue';
import { createMemberAddress,deleteMemberAddress,getMemberAddresses,setDefaultMemberAddress,updateMemberAddress } from '../services/api.js';
const addresses=ref([]),loading=ref(true),saving=ref(false),editingId=ref(null),error=ref(''),success=ref('');
const blank=()=>({label:'Home',recipient_name:'',phone_number:'',address_line_1:'',address_line_2:'',city:'',province:'Western Cape',postal_code:'',is_default:false});const form=reactive(blank());
function reset(){Object.assign(form,blank());editingId.value=null}function edit(a){Object.assign(form,{label:a.label,recipient_name:a.recipient_name,phone_number:a.phone_number||'',address_line_1:a.address_line_1,address_line_2:a.address_line_2||'',city:a.city,province:a.province,postal_code:a.postal_code,is_default:Boolean(a.is_default)});editingId.value=a.address_id;window.scrollTo({top:0,behavior:'smooth'})}
async function load(){loading.value=true;error.value='';try{const r=await getMemberAddresses();addresses.value=r.addresses||[]}catch(e){error.value=e.response?.data?.message||'Unable to load your addresses.'}finally{loading.value=false}}
async function save(){saving.value=true;error.value='';success.value='';try{if(editingId.value)await updateMemberAddress(editingId.value,{...form});else await createMemberAddress({...form});success.value='Address saved.';reset();await load()}catch(e){error.value=e.response?.data?.message||'Unable to save this address.'}finally{saving.value=false}}
async function makeDefault(id){try{await setDefaultMemberAddress(id);success.value='Default address updated.';await load()}catch(e){error.value=e.response?.data?.message||'Unable to update the default address.'}}
async function remove(id){if(!window.confirm('Delete this address?'))return;try{await deleteMemberAddress(id);success.value='Address deleted.';await load()}catch(e){error.value=e.response?.data?.message||'Unable to delete this address.'}}
onMounted(load);
</script>
<style scoped>
.page{min-height:100vh;background:var(--sw-page-background);color:var(--sw-page-text);padding:40px 20px 80px}.wrap{max-width:1120px;margin:auto}.hero{padding:34px;border-radius:24px;background:var(--sw-page-gradient);border:1px solid var(--sw-input-border);display:flex;justify-content:space-between;align-items:flex-start;gap:20px}.hero span,.label{font:800 10px var(--sw-font-body);letter-spacing:.14em;color:var(--sw-gold-500)}h1{font:800 clamp(40px,7vw,68px)/.95 var(--sw-font-heading);margin:14px 0 10px;letter-spacing:-.06em}.hero p{margin:0;color:var(--sw-page-text-soft);max-width:650px}.back,.primary,.secondary{padding:11px 15px;border-radius:10px;text-decoration:none;font:800 11px var(--sw-font-body);cursor:pointer}.back,.secondary{border:1px solid var(--sw-input-border);background:var(--sw-page-surface);color:var(--sw-page-text)}.message,.success{margin-top:16px;padding:13px 15px;border-radius:12px}.message{color:#b42318;background:rgba(180,35,24,.07)}.success{color:#247747;background:rgba(55,170,105,.08)}.layout{display:grid;grid-template-columns:1.1fr .9fr;gap:18px;margin-top:18px}.panel{padding:25px;border-radius:22px;background:var(--sw-page-surface);border:1px solid var(--sw-input-border);box-shadow:var(--sw-card-shadow)}.panel-head{display:flex;justify-content:space-between;align-items:center;gap:15px}.panel h2{font:800 26px var(--sw-font-heading);margin:8px 0 18px}.count,.tag,.default{font:800 9px var(--sw-font-body);letter-spacing:.08em}.count{padding:6px 9px;border-radius:99px;background:rgba(121,93,137,.1)}.addresses{display:grid;gap:10px}.address-card{padding:16px;border:1px solid var(--sw-input-border);border-radius:16px}.address-top{display:flex;justify-content:space-between;gap:10px}.address-top strong{display:block;margin-top:7px;font:800 14px var(--sw-font-body)}.tag{color:var(--sw-purple-700)}.default{color:var(--sw-gold-500)}.address-card p{color:var(--sw-page-text-soft);font:11px/1.6 var(--sw-font-body);margin:12px 0 4px}.address-card small{color:var(--sw-page-text-muted);font-size:10px}.address-actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:14px}.address-actions button{border:1px solid var(--sw-input-border);border-radius:8px;background:transparent;color:var(--sw-page-text);padding:7px 9px;font:700 9px var(--sw-font-body);cursor:pointer}.address-actions .danger{color:#b42318}.empty{padding:35px 10px;text-align:center;color:var(--sw-page-text-soft);font-size:12px;line-height:1.6}.form h2{margin-bottom:20px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.grid label{display:grid;gap:6px;color:var(--sw-page-text-soft);font:700 10px var(--sw-font-body)}.grid .wide{grid-column:1/-1}.grid input{width:100%;box-sizing:border-box;padding:11px 12px;border:1px solid var(--sw-input-border);border-radius:10px;background:var(--sw-page-background);color:var(--sw-page-text);outline:none}.grid input:focus{border-color:var(--sw-purple-700);box-shadow:0 0 0 3px rgba(121,93,137,.12)}.check{display:flex;align-items:center;gap:8px;margin-top:15px;color:var(--sw-page-text-soft);font:700 10px var(--sw-font-body)}.check input{accent-color:var(--sw-purple-700)}.form-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:20px}.primary{border:0;background:var(--sw-purple-700);color:#fff}.primary:disabled{opacity:.5;cursor:not-allowed}.secondary{border:1px solid var(--sw-input-border)}@media(max-width:800px){.layout{grid-template-columns:1fr}}@media(max-width:560px){.hero{flex-direction:column}.grid{grid-template-columns:1fr}.grid .wide{grid-column:auto}.form-actions{flex-direction:column}.form-actions>*{width:100%;box-sizing:border-box;text-align:center}}
</style>
